// @FIGURE_CODE_BEGIN
(function () {
  var W = 1520, H = 1050;
  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, W, H);

  var SERIF = 'Georgia, "Times New Roman", serif';
  var ORANGE = '#e8710a', ORANGE_BAND = '#ffc78f';

  var HULL = [[458, 883], [1199, 792], [1320, 573], [580, 143], [243, 637]];
  var INTER = [[428, 463], [581, 449], [719, 451], [827, 420], [1058, 451], [645, 527], [1120, 573], [1166, 697]];
  var CENTROID = [760, 605];
  var RAYLEN = [428, 150, 187, 242, 183];
  var ARCR = [370, 102, 120, 172, 186];

  var ALL = [];
  HULL.forEach(function (p, i) { ALL.push({ p: p, hull: true, idx: i }); });
  INTER.forEach(function (p, i) { ALL.push({ p: p, hull: false, idx: i }); });

  function dirSign(v) { return v <= 2 ? 1 : -1; }

  function polarAngle(from, to, s) {
    var a = Math.atan2(-(to[1] - from[1]), to[0] - from[0]);
    var ref = s > 0 ? 0 : Math.PI;
    var d = a - ref;
    while (d < 0) d += 2 * Math.PI;
    while (d >= 2 * Math.PI) d -= 2 * Math.PI;
