  // per-vertex ray lengths and arc radii tuned to the source proportions
  var RAYLEN = [435, 150, 186, 246, 190];
  var ARCR   = [375, 108, 150, 186, 126];

  var BAND_W = 21, BAND_OFF = 5;
  var R_HULL = 13, R_INT = 11.5;

  var ALL = [];
  HULL.forEach(function (p, i) { ALL.push({ p: p, hull: true, idx: i }); });
  INTER.forEach(function (p, i) { ALL.push({ p: p, hull: false, idx: i }); });

  function dirSign(v) { return v <= 2 ? 1 : -1; }

  function polarAngle(from, to, s) {
    var a = Math.atan2(-(to[1] - from[1]), to[0] - from[0]);
    var ref = s > 0 ? 0 : Math.PI;
    var d = a - ref;
    while (d < 0) d += 2 * Math.PI;
    while (d >= 2 * Math.PI) d -= 2 * Math.PI;
    return d;
  }
  function edgeDelta(v) { return polarAngle(HULL[v], HULL[(v + 1) % 5], dirSign(v)); }
  function deg(r) { return r * 180 / Math.PI; }

  // ── layers ──────────────────────────────────────────────────────────────
  var gHull = draw.group(), gRays = draw.group(), gDash = draw.group(),
      gChain = draw.group(), gCand = draw.group(), gPts = draw.group(), gLab = draw.group();

  function txt(g, s, x, y, size, o) {
    o = o || {};
    var t = g.plain(s).font({
      family: SERIF, size: size,
      anchor: o.anchor || 'middle',
      style: o.italic ? 'italic' : 'normal'
    }).attr({ x: x, y: y, fill: o.fill || '#000' });
    if (o.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 6, 'stroke-linejoin': 'round' });
    return t;
  }

  // vertex label with a real baseline-shifted subscript: p + <tspan dy>digit
  function vlabel(g, i, x, y, size, anchor) {
    var t = g.plain('').attr({
      x: x, y: y, fill: '#000',
      'text-anchor': anchor || 'start',
      'paint-order': 'stroke', stroke: '#fff',
      'stroke-width': 7, 'stroke-linejoin': 'round'
    }).font({ family: SERIF, size: size, style: 'italic' });
    var n = t.node;
    while (n.firstChild) n.removeChild(n.firstChild);
    var a = document.createElementNS(SVGNS, 'tspan');
    a.textContent = 'p';
    var b = document.createElementNS(SVGNS, 'tspan');
    b.textContent = String(i);
    b.setAttribute('font-size', (size * 0.68).toFixed(1));
    b.setAttribute('font-style', 'normal');
    b.setAttribute('dx', (size * 0.04).toFixed(1));
    b.setAttribute('dy', (size * 0.24).toFixed(1));
    n.appendChild(a); n.appendChild(b);
    return t;
  }

  function arrowHead(g, x, y, ux, uy, size, color, op) {
    var px = -uy, py = ux;
    g.polygon([
      [x, y],
      [x - size * ux + size * 0.36 * px, y - size * uy + size * 0.36 * py],
      [x - size * ux - size * 0.36 * px, y - size * uy - size * 0.36 * py]
    ]).fill(color).stroke('none').opacity(op == null ? 1 : op);
  }

  function arcPts(cx, cy, r, a0, a1) {
    var n = Math.max(12, Math.round(Math.abs(a1 - a0) / 0.04)), pts = [];
    for (var i = 0; i <= n; i++) {
      var a = a0 + (a1 - a0) * i / n;
      pts.push([cx + r * Math.cos(a), cy - r * Math.sin(a)]);
    }
    return pts;
  }

  // ── static: dashed chain-splitting line ─────────────────────────────────
  (function () {
    var d = [HULL[3][0] - HULL[0][0], HULL[3][1] - HULL[0][1]];
    var A = [HULL[0][0] - 0.18 * d[0], HULL[0][1] - 0.18 * d[1]];
    var B = [HULL[0][0] + 1.16 * d[0], HULL[0][1] + 1.16 * d[1]];
    gDash.line(A[0], A[1], B[0], B[1]).stroke({ color: '#111', width: 2.4, dasharray: '12,11' });
  })();

  // ── static: left/right chain label pairs, generously straddling the line ─
  function chainPair(yTxt, yArr, lTxtEnd, rTxtStart, lStart, lTip, rStart, rTip) {
    txt(gChain, 'left chain', lTxtEnd, yTxt, 37, { anchor: 'end' });
    txt(gChain, 'right chain', rTxtStart, yTxt, 37, { anchor: 'start' });
    gChain.line(lStart, yArr, lTip + 22, yArr).stroke({ color: '#000', width: 3.2 });
    arrowHead(gChain, lTip, yArr, -1, 0, 28, '#000');
    gChain.line(rStart, yArr, rTip - 22, yArr).stroke({ color: '#000', width: 3.2 });
    arrowHead(gChain, rTip, yArr, 1, 0, 28, '#000');
  }
  // top pair (dashed line sits near x≈590 here)
  chainPair(74, 112, 552, 630, 560, 430, 618, 752);
  // bottom pair (dashed line sits near x≈440 here)
  chainPair(1014, 968, 400, 480, 428, 296, 462, 612);

  // ── static: vertex labels (clear of hull edges, rays and dashed line) ───
  var LABPOS = [[486, 944, 'start'], [1224, 852, 'start'], [1348, 626, 'start'],
                [604, 218, 'start'], [172, 604, 'start']];
  LABPOS.forEach(function (L, i) { vlabel(gLab, i, L[0], L[1], 44, L[2]); });

  // ── state ───────────────────────────────────────────────────────────────
  var marchStates = ['start at p0', 'at p0 → find p1', 'at p1 → find p2',
    'at p2 → find p3', 'at p3 → find p4', 'at p4 → close to p0', 'hull complete'];
  var stepIdx = 0, chainView = 'both', demoIdx = 0;

  function isOriginal() { return stepIdx === 0 && chainView === 'both'; }
  function activeV() {
    if (isOriginal() || stepIdx === 6) return -1;
    return stepIdx === 0 ? 0 : stepIdx - 1;
  }
  function baseV() { var a = activeV(); return a >= 0 ? a : 0; }
  function chainEdgeOK(e) {
    return chainView === 'both' || (chainView === 'right' && e <= 2) || (chainView === 'left' && e >= 3);
  }
  function chainVertOK(v) {
    return chainView === 'both' || (chainView === 'right' && v <= 2) || (chainView === 'left' && v >= 3);
  }

  // ── render ──────────────────────────────────────────────────────────────
  function render() {
    gHull.clear(); gRays.clear();
    var orig = isOriginal(), av = activeV();

    for (var e = 0; e < 5; e++) {
      var a = HULL[e], b = HULL[(e + 1) % 5], st;
      if (stepIdx === 6 || orig) st = 'done';
      else if (stepIdx === 0) st = 'pending';
      else st = (e === stepIdx - 1) ? 'new' : (e < stepIdx - 1 ? 'done' : 'pending');

      var op = chainEdgeOK(e) ? 1 : 0.15;
      var band = st === 'new' ? ORANGE_BAND : (st === 'done' ? '#a8a8a8' : '#ededed');
      var line = st === 'new' ? ORANGE : (st === 'done' ? '#262626' : '#c9c9c9');
      var lw = st === 'new' ? 4 : (st === 'done' ? 2.8 : 2);

      var ex = b[0] - a[0], ey = b[1] - a[1];
      var el = Math.sqrt(ex * ex + ey * ey) || 1;
      var nx = -ey / el, ny = ex / el;
      var mx = (a[0] + b[0]) / 2, my = (a[1] + b[1]) / 2;
      if (nx * (mx - CENTROID[0]) + ny * (my - CENTROID[1]) < 0) { nx = -nx; ny = -ny; }
      var ox = BAND_OFF * nx, oy = BAND_OFF * ny;

      gHull.line(a[0] + ox, a[1] + oy, b[0] + ox, b[1] + oy)
        .stroke({ color: band, width: BAND_W, linecap: 'round' }).opacity(op);
      gHull.line(a[0], a[1], b[0], b[1])
        .stroke({ color: line, width: lw, linecap: 'round' }).opacity(op);
    }

    for (var v = 0; v < 5; v++) {
      var c = HULL[v], s = dirSign(v), act = (v === av);
      var col = act ? ORANGE : ((orig || stepIdx === 6) ? '#000' : '#b7b7b7');
      var wdt = act ? 3.2 : 2.2;
      var op2 = (chainVertOK(v) ? 1 : 0.13) * (act ? 1 : ((orig || stepIdx === 6) ? 1 : 0.8));

      gRays.line(c[0] - s * 66, c[1], c[0] + s * (RAYLEN[v] - 22), c[1])
        .stroke({ color: col, width: wdt }).opacity(op2);
      arrowHead(gRays, c[0] + s * RAYLEN[v], c[1], s, 0, 27, col, op2);
      gRays.line(c[0], c[1] - 30, c[0], c[1] + 30).stroke({ color: col, width: wdt }).opacity(op2);

      var ref = s > 0 ? 0 : Math.PI, d = edgeDelta(v);
      gRays.polyline(arcPts(c[0], c[1], ARCR[v], ref, ref + d))
        .fill('none').stroke({ color: col, width: act ? 3.4 : 1.9 }).opacity(op2);

      if (act) {
        var am = ref + d / 2, rr = ARCR[v] + 48;
        txt(gRays, deg(d).toFixed(1) + '°',
          c[0] + rr * Math.cos(am), c[1] - rr * Math.sin(am), 31,
          { fill: ORANGE, halo: true });
      }
    }
    updateReadouts();
  }

  // ── points with hover / click ───────────────────────────────────────────
  ALL.forEach(function (q) {
    var r = q.hull ? R_HULL : R_INT;
    var c = gPts.circle(r * 2).center(q.p[0], q.p[1]).fill('#000').css('cursor', 'pointer');
    var hit = gPts.circle(46).center(q.p[0], q.p[1]).fill('#fff').opacity(0).css('cursor', 'pointer');
    [c, hit].forEach(function (el) {
      el.on('mouseenter', function () { showCandidate(q); });
      el.on('mousemove', function (ev) { showTooltip(candText(q), ev); });
      el.on('mouseleave', function () { gCand.clear(); hideTooltip(); });
      el.on('click', function () {
        var b = baseV(), ang = q.p === HULL[b] ? null : deg(polarAngle(HULL[b], q.p, dirSign(b)));
        showPopup(q.hull ? 'Hull vertex p' + q.idx : 'Interior candidate',
          q.p === HULL[b]
            ? 'This is the current hull vertex: the reference ray and all candidate angles are measured from here.'
            : 'From p' + b + ' this point subtends a polar angle of ' + ang.toFixed(1) + '° above the reference ray. '
            + 'The winner is p' + ((b + 1) % 5) + ' at only ' + deg(edgeDelta(b)).toFixed(1) + '°. '
            + 'Gift wrapping simply keeps the minimum — no sorting of the point set is ever required.');
      });
    });
  });

  function candText(q) {
    var b = baseV();
    if (q.p === HULL[b]) return 'p' + b + ' — current hull vertex (angles measured from here)';
    var a = deg(polarAngle(HULL[b], q.p, dirSign(b)));
    var w = deg(edgeDelta(b));
    var tag = (q.hull && q.idx === (b + 1) % 5)
      ? ' — smallest angle, so it joins the hull'
      : ' vs winner ' + w.toFixed(1) + '° — rejected';
    return 'angle from p' + b + ': ' + a.toFixed(1) + '°' + tag;
  }

  function showCandidate(q) {
    gCand.clear();
    var b = baseV(), c = HULL[b];
    if (q.p === c) return;
    gCand.line(c[0], c[1], q.p[0], q.p[1])
      .stroke({ color: ORANGE, width: 2.4, dasharray: '9,7' }).opacity(0.95);
    var a = polarAngle(c, q.p, dirSign(b));
    var rr = 66 + ARCR[b] * 0.25, ref = dirSign(b) > 0 ? 0 : Math.PI;
    gCand.polyline(arcPts(c[0], c[1], rr, ref, ref + a))
      .fill('none').stroke({ color: ORANGE, width: 2, dasharray: '6,5' }).opacity(0.9);
    var mx = c[0] + (q.p[0] - c[0]) * 0.58, my = c[1] + (q.p[1] - c[1]) * 0.58;
    txt(gCand, deg(a).toFixed(1) + '°', mx, my - 22, 29, { fill: ORANGE, halo: true });
  }

  // ── UI wiring ───────────────────────────────────────────────────────────
  var DEMO = [
    { t: 'The point set and its hull', n: 'Thirteen points sit in the plane; the thick gray polygon through p₀, p₁, p₂, p₃, p₄ is the convex hull we want to discover. A dashed line through the lowest point p₀ and the highest point p₃ splits the boundary into a right chain and a left chain.', s: { m: 'start at p0', c: 'both' } },
    { t: 'Start at the lowest point', n: 'The march begins at p₀, guaranteed to be on the hull because it is lowest. A horizontal ray points right from p₀, and every other point\'s polar angle above that ray is measured.', s: { m: 'start at p0', c: 'right' } },
    { t: 'Smallest angle wins: p₁', n: 'The arc at p₀ is very narrow — p₁ subtends the smallest polar angle of all candidates, so the edge p₀p₁ joins the hull. Hover an interior point to see its larger angle and why it loses.', s: { m: 'at p0 → find p1', c: 'right' } },
    { t: 'Wrapping up the right chain', n: 'From p₁ the rightward ray sweeps again and picks p₂; from p₂ the arc is nearly a half turn before it reaches p₃. Each new vertex is found with the same minimum-angle rule.', s: { m: 'at p2 → find p3', c: 'right' } },
    { t: 'Flip at the top: the left chain', n: 'p₃ is the highest point, so the right chain ends. Now the reference ray points left, and the same minimum-angle rule walks back down through p₄.', s: { m: 'at p3 → find p4', c: 'left' } },
    { t: 'Close the loop', n: 'From p₄ the leftward ray sweeps a wide arc to p₀, closing the polygon. All eight interior points were examined at every step and rejected every time.', s: { m: 'hull complete', c: 'both' } }
  ];

  function updateReadouts() {
    var ms = document.getElementById('marchStateLabel');
    if (ms) ms.textContent = 'march state: ' + marchStates[stepIdx];
    var sl = document.getElementById('stepLabel');
    if (sl) sl.textContent = 'step ' + (demoIdx + 1) + ' / ' + DEMO.length + ' · ' + DEMO[demoIdx].t;
    var nn = document.getElementById('demoNarration');
    if (nn) nn.textContent = DEMO[demoIdx].n;
  }

  window.trigger_marchStep = function () {
    stepIdx = (stepIdx + 1) % marchStates.length;
    gCand.clear(); hideTooltip(); render();
  };
  window.toggle_chainView = function (v) {
    chainView = v; gCand.clear(); render();
  };
  window.applyDemo = function (i) {
    demoIdx = Math.max(0, Math.min(DEMO.length - 1, i));
    var s = DEMO[demoIdx].s;
    stepIdx = marchStates.indexOf(s.m);
    chainView = s.c;
    var sel = document.getElementById('chainViewInput');
    if (sel) sel.value = chainView;
    gCand.clear(); hideTooltip(); render();
  };
  window.nextStep = function () { applyDemo(demoIdx + 1); };
  window.prevStep = function () { applyDemo(demoIdx - 1); };
  window.resetAll = function () { applyDemo(0); };

  applyDemo(0);
  window.__markRendered();
})();
